export class ExpiryStore {
  private records: Map<string, Entry> = new Map()
  trim(limit: number): void {
    if (this.records.size <= limit) { return }
    let chosen: string | undefined = undefined
    let earliest = Number.MAX_SAFE_INTEGER
    for (const [name, record] of this.records) {
      if (record.updatedAt < earliest) {
        earliest = record.updatedAt
        chosen = name
      }
    }
    if (chosen !== undefined) { this.records.delete(chosen) }
  }
}

